return Array.from({ length: 5 }, (_, i) => ({
  json: {
    test_id: i + 1
  }
}));

const predictions = $input.all();
const generatedItems = $('Generate Customer Case').all();

let categoryCorrect = 0;
let priorityCorrect = 0;
let validCases = 0;
let parseErrors = 0;

const details = [];

for (let i = 0; i < predictions.length; i++) {
  const predicted = predictions[i].json;

  let rawText =
    generatedItems[i].json.output[0].content[0].text;

  let expected;

  try {
    // 清掉模型偶爾加上的 Markdown code fence
    rawText = rawText
      .replace(/```json/gi, '')
      .replace(/```/g, '')
      .trim();

    // 如果前後混入其他文字，只擷取第一個 { 到最後一個 }
    const start = rawText.indexOf('{');
    const end = rawText.lastIndexOf('}');

    if (start === -1 || end === -1) {
      throw new Error('No JSON object found');
    }

    const jsonText = rawText.slice(start, end + 1);

    expected = JSON.parse(jsonText);

  } catch (error) {
    parseErrors++;

    details.push({
      test_case: i + 1,
      parse_error: true,
      raw_output: rawText,
      error_message: error.message
    });

    continue;
  }

  validCases++;

  const isCategoryCorrect =
    predicted.predicted_category === expected.expected_category;

  const isPriorityCorrect =
    predicted.predicted_priority === expected.expected_priority;

  if (isCategoryCorrect) categoryCorrect++;
  if (isPriorityCorrect) priorityCorrect++;

  details.push({
    test_case: i + 1,

    message: expected.message,

    expected_category: expected.expected_category,
    predicted_category: predicted.predicted_category,
    category_correct: isCategoryCorrect,

    expected_priority: expected.expected_priority,
    predicted_priority: predicted.predicted_priority,
    priority_correct: isPriorityCorrect,

    summary: predicted.summary,
    suggested_reply: predicted.suggested_reply,

    parse_error: false
  });
}

const categoryAccuracy =
  validCases > 0
    ? (categoryCorrect / validCases) * 100
    : 0;

const priorityAccuracy =
  validCases > 0
    ? (priorityCorrect / validCases) * 100
    : 0;

const overallCorrect =
  categoryCorrect + priorityCorrect;

const overallTotal =
  validCases * 2;

const overallAccuracy =
  overallTotal > 0
    ? (overallCorrect / overallTotal) * 100
    : 0;

return [
  {
    json: {
      total_cases: predictions.length,
      valid_cases: validCases,
      parse_errors: parseErrors,

      category_correct: categoryCorrect,
      category_accuracy:
        categoryAccuracy.toFixed(2) + "%",

      priority_correct: priorityCorrect,
      priority_accuracy:
        priorityAccuracy.toFixed(2) + "%",

      overall_correct: overallCorrect,
      overall_total: overallTotal,
      overall_accuracy:
        overallAccuracy.toFixed(2) + "%",

      details
    }
  }
];
